fn fibonacci(n: usize) -> Vec<i32> {
    // As per the problem statement, assume n >= 2 and values fit in i32.
    let mut ret: Vec<i32> = Vec::with_capacity(n);
    ret.push(0);
    ret.push(1);

    for i in 2..n {
        let next = ret[i - 1] + ret[i - 2];
        ret.push(next);
    }

    ret
}